import { useEffect, useState } from "react";
import { Animated, Easing, View } from "react-native";
import type { StyleProp, TextStyle, ViewProps, ViewStyle } from "react-native";
import { useTokens } from "../lib/rn-tokens";

export interface TextRevealProps extends Omit<ViewProps, "children"> {
  text: string;
  /** Delay before the first word, in seconds. */
  delay?: number;
  /** Extend the inner, named parts of the reveal: line or word. The React Native counterpart of `classNames`. */
  styles?: {
    line?: StyleProp<ViewStyle>;
    word?: StyleProp<TextStyle>;
  };
}

/** Each word rises out of a short offset and fades in, a beat after the one before it. */
function Word({ children, index, delay, style }: { children: string; index: number; delay: number; style: StyleProp<TextStyle> }) {
  const [progress] = useState(() => new Animated.Value(0));
  useEffect(() => {
    Animated.timing(progress, { toValue: 1, duration: 620, delay: delay * 1000 + index * 55, easing: Easing.out(Easing.cubic), useNativeDriver: true }).start();
  }, [delay, index, progress]);

  return (
    <Animated.Text
      style={[style, { opacity: progress, transform: [{ translateY: progress.interpolate({ inputRange: [0, 1], outputRange: [10, 0] }) }] }]}
    >
      {children}{" "}
    </Animated.Text>
  );
}

export function TextReveal({ text, delay = 0, style, styles: parts, ...props }: TextRevealProps) {
  const tokens = useTokens();
  const words = text.split(/\s+/).filter(Boolean);

  return (
    <View {...props} accessible accessibilityRole="header" accessibilityLabel={text} style={[{ flexDirection: "row", flexWrap: "wrap" }, style, parts?.line]}>
      {words.map((word, index) => (
        <Word key={`${word}-${index}`} index={index} delay={delay} style={[{ color: tokens.foreground, fontSize: 28, fontWeight: "600", lineHeight: 34, letterSpacing: -0.8 }, parts?.word]}>
          {word}
        </Word>
      ))}
    </View>
  );
}

export default TextReveal;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
  /** Four distinguishable colours for chart series, the counterpart of --series-1 to --series-4. */
  series: [string, string, string, string];
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
  series: ["#1f7dcf", "#7128a5", "#e58f00", "#009e84"],
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
  series: ["#55adff", "#9c37be", "#e66e00", "#00a861"],
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
